import{_ as a,o as t,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — List Workspace (FR 3.4.10)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-10-list-workspace/plan.md","filePath":"feature/agency-workspace/3-4-10-list-workspace/plan.md"}'),s={name:"feature/agency-workspace/3-4-10-list-workspace/plan.md"};function c(r,e,d,i,l,p){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="plan-—-list-workspace-fr-3-4-10" tabindex="-1">Plan — List Workspace (FR 3.4.10) <a class="header-anchor" href="#plan-—-list-workspace-fr-3-4-10" aria-label="Permalink to &quot;Plan — List Workspace (FR 3.4.10)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho user xem danh sách Workspace họ đang là <code>WorkspaceMember</code>.</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>WorkspaceServiceImpl.listMyWorkspaces()</code>, <code>WorkspaceServiceImpl.listManagedWorkspaces()</code></td></tr><tr><td>File đã có</td><td><code>WorkspaceController</code> (<code>GET /api/v1/workspaces</code>, <code>GET /api/v1/workspaces/my-managed</code>), <code>WorkspaceRepository</code>, <code>WorkspaceMemberRepository</code>, <code>WorkspaceResponse</code>, <code>ManagedWorkspaceResponse</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/workspaces</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;List&lt;WorkspaceResponse&gt;&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/my-managed</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;List&lt;ManagedWorkspaceResponse&gt;&gt;</span></span>
<span class="line"><span>   data = [{ id, name, role, memberCount }]</span></span></code></pre></div><p>Không lệch so với spec.md — cả 2 endpoint đã khớp code thật.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li>Flow A: <code>workspace_members</code> theo <code>userId = currentUser.id AND isActive = true</code> → lấy <code>workspaceId</code> → <code>workspaces.findAllById</code>.</li><li>Flow B: như trên nhưng lọc thêm <code>role = MANAGER</code>; với mỗi Workspace còn lại đếm <code>memberCount</code> qua <code>countByWorkspaceIdAndIsActiveTrue</code>.</li><li>Không migration.</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><ol><li>Query <code>workspace_members</code> active của current user.</li><li>Lấy <code>workspaceId</code> → <code>findAllById</code> trên <code>workspaces</code>.</li><li>Map → <code>WorkspaceResponse</code> (Flow A) hoặc <code>ManagedWorkspaceResponse</code> kèm <code>memberCount</code> (Flow B).</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>Workspace</code>/<code>WorkspaceMember</code> entity + repository (đã có)</td></tr><tr><td>Bị chặn</td><td><code>View Workspace Profile</code> (3.4.13), <code>Add/Remove Member</code> (3.4.19/3.4.21) — cùng repo</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Không có khái niệm &quot;Owner Agency thấy toàn bộ Workspace&quot;</strong> ở endpoint này — chỉ trả Workspace mà user có membership trực tiếp. Nếu BA muốn Owner Agency thấy toàn bộ Workspace con của Agency mình (kể cả chưa là member), cần endpoint riêng — hiện chưa có, ghi nhận là gap tiềm năng.</li><li><strong>2 query riêng biệt (Flow A/B) thay vì 1 query có filter role</strong> — chấp nhận vì đơn giản, số lượng Workspace/user nhỏ, không cần tối ưu N+1 ở quy mô hiện tại.</li></ul>`,15)])])}const k=a(s,[["render",c]]);export{u as __pageData,k as default};
